{
  "title": "社团选拔日",
  "scene": "今天是学校社团的选拔日，你来到了美术社的选拔现场。美术社的会长小明看起来有点紧张，他告诉你们这次选拔的题目是画一幅校园风景画。但是，他不小心把重要的画纸弄丢了，只剩下几张普通的白纸。小明说，如果用这些纸，可能画不出最好的效果。你们旁边有一位美术老师，看起来很和蔼。",
  "goal": "帮助小明解决画纸的问题",
  "clue": "美术老师的描述",
  "choices": [
    {
      "id": "A",
      "text": "用普通白纸画",
      "outcome": "虽然用普通白纸画效果没有那么好，但你还是用心画了一幅画，会长小明非常感谢你。虽然没有得奖，但你还是顺利加入了美术社。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "向美术老师求助",
      "outcome": "你鼓起勇气向美术老师寻求帮助，老师非常乐意地提供了几张高质量的画纸。你用这些纸画了一幅美丽的校园风景画，成功赢得了评委的认可，顺利加入了美术社。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "放弃参加选拔",
      "outcome": "你决定不参加这次选拔，虽然小明很失望，但他还是感谢你的支持。下次选拔时，你可以再尝试加入。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
